const brut = String($json.body?.siret ?? $json.siret ?? '');
const siret = brut.replace(/[\s.\-]/g, '');
if (!/^\d{14}$/.test(siret)) {
  return { json: { siret, format_ok: false, reponse: { valide: false, raison: 'format' } } };
}
const chiffres = siret.split('').map(Number);
let somme = 0;
for (let i = 0; i < 14; i++) {
  let c = chiffres[13 - i];
  if (i % 2 === 1) { c = c * 2; if (c > 9) c = c - 9; }
  somme += c;
}
let cleOk = somme % 10 === 0;
if (!cleOk && siret.startsWith('356000000')) {
  cleOk = chiffres.reduce((a, b) => a + b, 0) % 5 === 0;
}
if (!cleOk) {
  return { json: { siret, format_ok: false, reponse: { valide: false, raison: 'numero_invalide' } } };
}
return { json: { siret, format_ok: true } };

const siret = $('Vérifier le format du SIRET').item.json.siret;
const resultats = Array.isArray($json.results) ? $json.results : [];
let entreprise = null;
let etab = null;
for (const r of resultats) {
  const liste = Array.isArray(r.matching_etablissements) ? r.matching_etablissements : [];
  const trouve = liste.find(e => e.siret === siret) || (r.siege && r.siege.siret === siret ? r.siege : null);
  if (trouve) { entreprise = r; etab = trouve; break; }
}
if (!entreprise) {
  return { json: { reponse: { valide: false, raison: 'introuvable' } } };
}
if (etab.etat_administratif === 'F' || entreprise.etat_administratif === 'C') {
  return { json: { reponse: { valide: false, raison: 'entreprise_fermee', nom: entreprise.nom_complet || null } } };
}
const formes = {
