  '43.99D': 'Autres travaux spécialisés de construction',
  '43.99E': 'Location avec opérateur de matériel de construction'
};
const code = etab.activite_principale || entreprise.activite_principale || '';
const batiment = /^4[123]/.test(code);
const nj = String(entreprise.nature_juridique || '');
return {
  json: {
    reponse: {
      valide: true,
      siret,
      nom: entreprise.nom_complet || entreprise.nom_raison_sociale || null,
      forme_juridique: formes[nj] || (nj ? 'Code ' + nj : null),
      adresse: etab.adresse || null,
      code_activite: code || null,
      libelle_activite: activites[code] || (batiment ? 'Bâtiment' : 'Hors bâtiment'),
      batiment,
      rge: (Array.isArray(etab.liste_rge) && etab.liste_rge.length > 0) || entreprise.complements?.est_rge === true
    }
  }
};
